class_name SonarVision
extends RefCounted
## THE mechanic (spec.systems.sonar): a player-triggered, cooldown-gated ping.
## A ring expands from the player over Feel.RING_EXPAND_TIME; each entity is
## revealed (visibility 1.0) the moment the ring reaches it — cinematic, not
## instant. The echo then holds Feel.REVEAL_TIME and fades to 0 over
## Feel.ECHO_FADE (total lifetime Feel.ECHO_TOTAL_TIME).
## Pure logic: dictionaries of entity id -> visibility. UI/scene code reads it.

var player_pos := Vector2.ZERO
var ping_count := 0
var elapsed := 0.0                 # total simulated time (sum of tick deltas)
var last_ping_origin := Vector2.ZERO   # creatures home in on this (milestone 2)

var _cooldown_left := 0.0
var _ring_time := -1.0             # < 0 = no active ping
var _positions := {}               # id -> Vector2
var _vis := {}                     # id -> float 0..1
var _echo_age := {}                # id -> s since the ring reached it
var _revealed_this_ping := {}      # id -> bool


# ------------------------------------------------------------- entities --

func register(id: String, pos: Vector2) -> void:
	_positions[id] = pos
	_vis[id] = 0.0
	_echo_age[id] = 0.0
	_revealed_this_ping[id] = false


func unregister(id: String) -> void:
	_positions.erase(id)
	_vis.erase(id)
	_echo_age.erase(id)
	_revealed_this_ping.erase(id)


func has_entity(id: String) -> bool:
	return _positions.has(id)


func set_entity_position(id: String, pos: Vector2) -> void:
	if _positions.has(id):
		_positions[id] = pos


func set_player_pos(pos: Vector2) -> void:
	player_pos = pos


func get_visibility(id: String) -> float:
	return float(_vis.get(id, 0.0))


## Brightest current echo across all entities (HUD/tests convenience).
func max_visibility() -> float:
	var best := 0.0
	for v in _vis.values():
		best = maxf(best, float(v))

class_name PSX
extends RefCounted
## THE PSX LAW, M4 (spec psx_law) — code-built shaders, no assets.
##
## low_res:      the stage renders into a 320x240 SubViewport (Feel consts),
##               upscaled nearest-neighbor by a full-rect TextureRect.
## vertex_wobble: the spatial shader below snaps every vertex's clip-space XY
##               to the virtual grid (Feel.PSX_SNAP_GRID cells across the 320
##               target = 2 px quantization) — the PSX swimming look.
## affine_hint:  the vertex shader pre-multiplies UV by clip.w and the fragment
##               divides it back — the interpolated varying is then AFFINE, the
##               wobbly PSX texture warping; all textures nearest-filtered.
## dither:       the screen TextureRect runs a 4x4 Bayer ordered dither that
##               quantizes to Feel.PSX_COLOR_BITS per channel (15-bit color).
## fog:          Feel.FOG_DENSITY exponential-squared toward Feel.COL_FOG,
##               computed in-shader (render_mode fog_disabled opts out of the
##               Environment fog so the one Feel number stays the only fog).
##
## The override law: the world's materials stay StandardMaterial3D (the M2
## battery reads them as the taxonomy's law record); the PSX shader rides as
## GeometryInstance3D.material_override, mirroring the SAME Feel colors via
## uniforms (style()/style_emission()). One source of truth: Feel.
##
## Lighting is deliberately hand-rolled (render_mode unshaded): a single sun
## direction + ambient, both uniform-fed from the real stage nodes by
## set_world_lights() — deterministic, no dependence on the light pipeline.

const SOLID_SRC := "
shader_type spatial;
render_mode unshaded, skip_vertex_transform, fog_disabled, shadows_disabled, cull_back;

uniform vec3 sun_dir_world = vec3(-0.3, -0.8, -0.4);
uniform vec3 sun_color = vec3(1.0, 1.0, 1.0);
uniform vec3 ambient = vec3(0.35, 0.42, 0.55);
uniform vec4 albedo_color = vec4(1.0, 1.0, 1.0, 1.0);
uniform vec3 emission_color = vec3(0.0, 0.0, 0.0);
uniform float emission_energy = 0.0;
uniform float metallic_amount = 0.0;
uniform float fog_density = 0.02;
uniform vec3 fog_color = vec3(0.043, 0.059, 0.098);
uniform vec2 snap_cells = vec2(80.0, 60.0);
uniform sampler2D albedo_tex : source_color;

varying vec3 v_light;
varying float v_depth;
varying vec2 v_uv_w;
varying float v_w;

void vertex() {
	vec4 view_pos = MODELVIEW_MATRIX * vec4(VERTEX, 1.0);
	vec4 clip = PROJECTION_MATRIX * view_pos;
	if (clip.w > 0.000001) {
		vec2 ndc = clip.xy / clip.w;
		vec2 snapped = floor(ndc * snap_cells + vec2(0.5)) / snap_cells;
		clip = vec4(snapped * clip.w, clip.zw);
		view_pos = INV_PROJECTION_MATRIX * clip;
	}
	v_w = clip.w;
	v_uv_w = UV * clip.w;
	vec3 n = normalize((MODELVIEW_MATRIX * vec4(NORMAL, 0.0)).xyz);

class_name Hiscore
extends RefCounted
## THE HISCORE (spec.systems_law: hiscore persists, user://). One int, the
## best score ever banked; save_best never regresses. Static — there is
## exactly one best, and tests + scene both want it without wiring.

const SAVE_PATH := "user://powder_run_hiscore.dat"


static func load_best() -> int:
	if not FileAccess.file_exists(SAVE_PATH):
		return 0
	var f := FileAccess.open(SAVE_PATH, FileAccess.READ)
	if f == null:
		return 0
	var best := int(f.get_line().to_float())
	f.close()
	return maxi(0, best)


## Banks a finished run: stores max(current best, score), returns the stored
## best (never regresses — a worse run cannot rewrite history).
static func save_best(score: int) -> int:
	var best := maxi(load_best(), score)
	var f := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if f == null:
		return best
	f.store_line(str(best))
	f.close()
	return best

