class_name LetterTray
extends RefCounted
## The build layer: tapping tray letters moves them to the build slot in tap
## order; backspace pops the last; clear empties the slot. judge() names an
## illegal build's cause (TOO SHORT / LETTER NOT IN TRAY) BEFORE the dictionary
## is ever asked — an illegal build never reaches the dictionary.

const REASON_TOO_SHORT := "TOO SHORT"
const REASON_NOT_IN_TRAY := "LETTER NOT IN TRAY"

var letters: Array = []   ## the dealt multiset (Array[String])
var used: Array = []      ## parallel to letters: true once a tile is in the slot
var slot: Array = []      ## tray indices in tap order


func setup(dealt: Array) -> void:
	letters = dealt.duplicate()
	used = []
	slot = []
	for i in range(letters.size()):
		used.append(false)


## Tap a tray tile into the build slot. Returns false for an out-of-range or
## already-used tile (a tile already in the slot cannot be tapped again —
## borrowing letters you were not dealt is structurally impossible via taps).
func tap(index: int) -> bool:
	if index < 0 or index >= letters.size():
		return false
	if bool(used[index]):
		return false
	used[index] = true
	slot.append(index)
	return true


## Pop the last tapped tile back to the tray. False when the slot is empty.
func backspace() -> bool:
	if slot.is_empty():
		return false
	used[int(slot.pop_back())] = false
	return true


## Empty the slot; every tile returns to the tray.
func clear() -> void:
	for i in slot:
		used[int(i)] = false
	slot = []


## The build slot's word, in tap order.
func slot_word() -> String:
	var parts := PackedStringArray()
	for i in slot:
		parts.append(String(letters[int(i)]))
	return "".join(parts)


## True when the build slot holds every dealt letter (the all-letters build).
